import process from "node:process";

import { createEnv } from "@t3-oss/env-core";
import { isProduction } from "std-env";
import { z } from "zod";

import { normalizedUrlSchema } from "#@/utils/url";

console.debug("⏳ [ENV_SERVER] Loading environment variables...", {
  SOURCE_COMMIT: process.env.WORKERS_CI_COMMIT_SHA,
  VITE_SERVER_URL: process.env.VITE_SERVER_URL,
  VITE_WEB_URL: process.env.VITE_WEB_URL
});

export const ENV_SERVER = createEnv({
  emptyStringAsUndefined: true,
  runtimeEnv: process.env,
  server: {
    VITE_SERVER_URL: isProduction
      ? normalizedUrlSchema
      : normalizedUrlSchema.default("http://localhost:5001"),
    VITE_WEB_URL: isProduction
      ? normalizedUrlSchema
      : normalizedUrlSchema.default("http://localhost:3000"),
    DATABASE_URL: z.string().min(1),
    BETTER_AUTH_SECRET: z.string().min(32),
    NODE_ENV: z.enum(["development", "production"]).default("development"),
    WORKERS_CI_COMMIT_SHA: z.string().min(1).default("unknown"), // autogenerated by Coolify, needs to be manually set otherwise
    ENABLE_OPEN_API_DOCS: z.stringbool().default(false),
    IS_BUILD: z.stringbool().default(false), // set to 'true' during build, can be used to conditionally disable features that should only run during runtime and not during build/prerendering
    GITHUB_WEBHOOK_SECRET: z.string().min(1).optional(),
    GITHUB_CLIENT_ID: z.string().min(1),
    GITHUB_CLIENT_SECRET: z.string().min(1)
  }
});

console.debug("✅ [ENV_SERVER] Successfully loaded environment variables.");
